import Foundation

public struct ArtifactsOpenRequest: Codable, Equatable, Sendable {
    /// Generated by the caller. Reopening an existing target ignores this ID.
    public var id: String
    public var hostID: String
    public var hostLabel: String
    public var target: ArtifactsTarget
    public var title: String
    public var origin: String
    public var sessionHint: String?
    /// A browser's explicit new tab: it never reuses a tab, even one at the
    /// identical target. Automatic opens (links, Files, agent follows) leave
    /// it false and focus the tab already showing their target. Optional on
    /// the wire and omitted when false.
    public var newTab: Bool

    public init(
        id: String, hostID: String, hostLabel: String, target: ArtifactsTarget,
        title: String, origin: String = "quickOpen", sessionHint: String? = nil,
        newTab: Bool = false
    ) {
        self.id = id
        self.hostID = hostID
        self.hostLabel = hostLabel
        self.target = target
        self.title = title
        self.origin = origin
        self.sessionHint = sessionHint
        self.newTab = newTab
    }

    private enum CodingKeys: String, CodingKey { case id, hostID, hostLabel, target, title, origin, sessionHint, newTab }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id)
        hostID = try c.decode(String.self, forKey: .hostID)
        hostLabel = try c.decode(String.self, forKey: .hostLabel)
        target = try c.decode(ArtifactsTarget.self, forKey: .target)
        title = try c.decode(String.self, forKey: .title)
        origin = try c.decode(String.self, forKey: .origin)
        sessionHint = try c.decodeIfPresent(String.self, forKey: .sessionHint)
        newTab = try c.decodeIfPresent(Bool.self, forKey: .newTab) ?? false
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(id, forKey: .id)
        try c.encode(hostID, forKey: .hostID)
        try c.encode(hostLabel, forKey: .hostLabel)
        try c.encode(target, forKey: .target)
        try c.encode(title, forKey: .title)
        try c.encode(origin, forKey: .origin)
        try c.encodeIfPresent(sessionHint, forKey: .sessionHint)
        if newTab { try c.encode(true, forKey: .newTab) }
    }
}

/// Flat action JSON: {"type":"select","tabID":"t1","nowMillis":10}.
/// `open` carries `open`; `fetched` carries `cache`; `navigate` carries
/// `tabID`, `target` and `title`. Optional stat fields mean "not observed",
/// rather than clearing known metadata.
public enum ArtifactsAction: Codable, Equatable, Sendable {
    case open(ArtifactsOpenRequest, nowMillis: Int64)
    /// The address bar's Return on a tab: that tab shows `target` instead,
    /// on its own host. A change snapshot neither navigates nor is a
    /// destination; the platform opens those as a new tab.
    case navigate(tabID: String, target: ArtifactsTarget, title: String, nowMillis: Int64)
    case select(tabID: String, nowMillis: Int64)
    case close(tabID: String, nowMillis: Int64)
    case closeAll(hostID: String, nowMillis: Int64)
    case pin(tabID: String, pinned: Bool, nowMillis: Int64)
    case setFilter(ArtifactsFilter, nowMillis: Int64)
    case titleLearned(tabID: String, title: String, nowMillis: Int64)
    case fetched(tabID: String, cache: ArtifactsCacheMetadata, nowMillis: Int64)
    case remoteStatObserved(tabID: String, remoteMTime: Int64?, size: Int64?, visible: Bool, nowMillis: Int64)
    case agentEditObserved(hostID: String, path: String, nowMillis: Int64)
    case hostRemoved(hostID: String, nowMillis: Int64)
    case hostRelabelled(hostID: String, label: String, nowMillis: Int64)

    private struct Wire: Codable {
        var type: String
        var nowMillis: Int64
        var open: ArtifactsOpenRequest?
        var tabID: String?
        var hostID: String?
        var pinned: Bool?
        var filter: ArtifactsFilter?
        var title: String?
        var cache: ArtifactsCacheMetadata?
        var remoteMTime: Int64?
        var size: Int64?
        var visible: Bool?
        var path: String?
        var label: String?
        var target: ArtifactsTarget?
    }

    public init(from decoder: Decoder) throws {
        let w = try Wire(from: decoder)
        switch w.type {
        case "open":
            guard let v = w.open else { throw ArtifactsCoding.invalid(decoder, "missing open") }
            self = .open(v, nowMillis: w.nowMillis)
        case "select", "close", "pin", "titleLearned", "fetched", "remoteStatObserved", "navigate":
            guard let id = w.tabID else { throw ArtifactsCoding.invalid(decoder, "missing tabID") }
            switch w.type {
            case "select": self = .select(tabID: id, nowMillis: w.nowMillis)
            case "navigate":
                guard let target = w.target, let title = w.title else { throw ArtifactsCoding.invalid(decoder, "missing navigation") }
                self = .navigate(tabID: id, target: target, title: title, nowMillis: w.nowMillis)
            case "close": self = .close(tabID: id, nowMillis: w.nowMillis)
            case "pin":
                guard let v = w.pinned else { throw ArtifactsCoding.invalid(decoder, "missing pinned") }
                self = .pin(tabID: id, pinned: v, nowMillis: w.nowMillis)
            case "titleLearned":
                guard let v = w.title else { throw ArtifactsCoding.invalid(decoder, "missing title") }
                self = .titleLearned(tabID: id, title: v, nowMillis: w.nowMillis)
            case "fetched":
                guard let v = w.cache else { throw ArtifactsCoding.invalid(decoder, "missing cache") }
                self = .fetched(tabID: id, cache: v, nowMillis: w.nowMillis)
            default:
                guard let visible = w.visible, w.size.map({ $0 >= 0 }) ?? true else {
                    throw ArtifactsCoding.invalid(decoder, "invalid stat")
                }
                self = .remoteStatObserved(tabID: id, remoteMTime: w.remoteMTime, size: w.size,
                                           visible: visible, nowMillis: w.nowMillis)
            }
        case "setFilter":
            guard let v = w.filter else { throw ArtifactsCoding.invalid(decoder, "missing filter") }
            self = .setFilter(v, nowMillis: w.nowMillis)
        case "closeAll", "agentEditObserved", "hostRemoved", "hostRelabelled":
            guard let host = w.hostID else { throw ArtifactsCoding.invalid(decoder, "missing hostID") }
            switch w.type {
            case "closeAll": self = .closeAll(hostID: host, nowMillis: w.nowMillis)
            case "hostRemoved": self = .hostRemoved(hostID: host, nowMillis: w.nowMillis)
            case "hostRelabelled":
                guard let v = w.label else { throw ArtifactsCoding.invalid(decoder, "missing label") }
                self = .hostRelabelled(hostID: host, label: v, nowMillis: w.nowMillis)
            default:
                guard let v = w.path else { throw ArtifactsCoding.invalid(decoder, "missing path") }
                self = .agentEditObserved(hostID: host, path: v, nowMillis: w.nowMillis)
            }
        default: throw ArtifactsCoding.invalid(decoder, "unknown action type")
        }
    }

    public func encode(to encoder: Encoder) throws {
        let w: Wire
        switch self {
        case let .open(v, now): w = Wire(type: "open", nowMillis: now, open: v)
        case let .navigate(id, target, title, now):
            w = Wire(type: "navigate", nowMillis: now, tabID: id, title: title, target: target)
        case let .select(id, now): w = Wire(type: "select", nowMillis: now, tabID: id)
        case let .close(id, now): w = Wire(type: "close", nowMillis: now, tabID: id)
        case let .closeAll(host, now): w = Wire(type: "closeAll", nowMillis: now, hostID: host)
        case let .pin(id, pinned, now): w = Wire(type: "pin", nowMillis: now, tabID: id, pinned: pinned)
        case let .setFilter(v, now): w = Wire(type: "setFilter", nowMillis: now, filter: v)
        case let .titleLearned(id, title, now): w = Wire(type: "titleLearned", nowMillis: now, tabID: id, title: title)
        case let .fetched(id, cache, now): w = Wire(type: "fetched", nowMillis: now, tabID: id, cache: cache)
        case let .remoteStatObserved(id, mtime, size, visible, now):
            w = Wire(type: "remoteStatObserved", nowMillis: now, tabID: id,
                     remoteMTime: mtime, size: size, visible: visible)
        case let .agentEditObserved(host, path, now):
            w = Wire(type: "agentEditObserved", nowMillis: now, hostID: host, path: path)
        case let .hostRemoved(host, now): w = Wire(type: "hostRemoved", nowMillis: now, hostID: host)
        case let .hostRelabelled(host, label, now):
            w = Wire(type: "hostRelabelled", nowMillis: now, hostID: host, label: label)
        }
        try w.encode(to: encoder)
    }
}

public struct ArtifactsReduction: Codable, Equatable, Sendable {
    public var state: ArtifactsState
    public var focusedTabID: String?
    public var evictedTabIDs: [String]
    /// Present on page opens, including a reused port tab, and on page
    /// navigations. Includes query and fragment so the platform navigates to
    /// the caller's exact location.
    public var navigatedPath: String?
}

public enum ArtifactsReducer {
    public static func reduce(_ state: ArtifactsState, _ action: ArtifactsAction) -> ArtifactsReduction {
        var state = state
        var navigation: String?
        switch action {
        case let .open(request, now):
            let target = ArtifactsPersistence.capped(request.target.normalized)
            guard target.isValid, !request.id.isEmpty, !request.hostID.isEmpty else { break }
            if let i = request.newTab ? nil : reusableTab(for: target, hostID: request.hostID, in: state) {
                state.tabs[i].viewedAt = now
                state.tabs[i].unseenChange = false
                state.tabs[i].hostLabel = request.hostLabel
                if case .page = target { state.tabs[i].target = target }
                state.selectedID = state.tabs[i].id
            } else if !state.tabs.contains(where: { $0.id == request.id }) {
                var tab = ArtifactTab(
                    id: request.id, hostID: request.hostID, hostLabel: request.hostLabel,
                    target: target, title: request.title, origin: request.origin, sessionHint: request.sessionHint,
                    openedAt: now, viewedAt: now
                )
                tab.cache = sharedCache(for: target, hostID: request.hostID, in: state)
                state.tabs.append(tab)
                state.selectedID = request.id
            } else { break }
            if case let .page(_, _, path) = target { navigation = path }
        case let .navigate(id, requested, title, now):
            let target = ArtifactsPersistence.capped(requested.normalized)
            guard target.isValid, let i = state.tabs.firstIndex(where: { $0.id == id }) else { break }
            if case .change = state.tabs[i].target { break }
            if case .change = target { break }
            if state.tabs[i].target != target {
                // What the tab knew about its old target does not describe the
                // new one; another tab's copy of the new target may.
                let shared = sharedCache(for: target, hostID: state.tabs[i].hostID, in: state)
                state.tabs[i].target = target
                state.tabs[i].kind = target.kind
                if !title.isEmpty { state.tabs[i].title = title }
                state.tabs[i].cache = shared
                state.tabs[i].agentEditedAt = nil
                state.tabs[i].origin = "quickOpen"
                state.tabs[i].sessionHint = nil
            }
            state.tabs[i].viewedAt = now
            state.tabs[i].unseenChange = false
            state.selectedID = id
            if case let .page(_, _, path) = target { navigation = path }
        case let .select(id, now):
            if let i = state.tabs.firstIndex(where: { $0.id == id }) {
                state.selectedID = id
                state.tabs[i].viewedAt = now
                state.tabs[i].unseenChange = false
            }
        case let .close(id, now):
            let host = state.tabs.first(where: { $0.id == id })?.hostID
            state.tabs.removeAll { $0.id == id }
            if state.selectedID == id { selectFallback(&state, hostID: host, now: now) }
        case let .closeAll(host, now), let .hostRemoved(host, now):
            let selectedHost = state.tabs.first(where: { $0.id == state.selectedID })?.hostID
            state.tabs.removeAll { $0.hostID == host }
            if selectedHost == host { selectFallback(&state, hostID: host, now: now) }
        case let .pin(id, pinned, _):
            if let i = state.tabs.firstIndex(where: { $0.id == id }) { state.tabs[i].pinned = pinned }
        case let .setFilter(filter, _): state.filter = filter
        case let .titleLearned(id, title, _):
            if let i = state.tabs.firstIndex(where: { $0.id == id }), !title.isEmpty { state.tabs[i].title = title }
        case let .fetched(id, metadata, now):
            if let i = state.tabs.firstIndex(where: { $0.id == id }), metadata.size >= 0 {
                var cache = metadata
                cache.fetchedAt = now
                cache.isStale = false
                state.tabs[i].cache = cache
                state.tabs[i].unseenChange = false
            }
        case let .remoteStatObserved(id, mtime, size, visible, _):
            guard let i = state.tabs.firstIndex(where: { $0.id == id }), let cache = state.tabs[i].cache else {
                return .init(state: state, focusedTabID: state.selectedID, evictedTabIDs: [])
            }
            let moved = mtime.map { $0 != cache.remoteMTime } ?? false
            let resized = size.map { $0 >= 0 && $0 != cache.size } ?? false
            guard moved || resized else { return .init(state: state, focusedTabID: state.selectedID, evictedTabIDs: []) }
            state.tabs[i].cache?.isStale = true
            state.tabs[i].unseenChange = !(state.selectedID == id && visible)
        case let .agentEditObserved(host, path, now):
            let path = ArtifactsPaths.normalize(path)
            let matches = state.tabs.indices.filter {
                guard state.tabs[$0].hostID == host, case let .file(tabPath) = state.tabs[$0].target else { return false }
                return ArtifactsPaths.normalize(tabPath).utf8.elementsEqual(path.utf8)
            }
            guard !matches.isEmpty else { return .init(state: state, focusedTabID: state.selectedID, evictedTabIDs: []) }
            for i in matches {
                state.tabs[i].agentEditedAt = now
                state.tabs[i].unseenChange = true
                state.tabs[i].cache?.isStale = true
            }
        case let .hostRelabelled(host, label, _):
            for i in state.tabs.indices where state.tabs[i].hostID == host { state.tabs[i].hostLabel = label }
        }
        let evicted = enforceCap(&state)
        return .init(state: state, focusedTabID: state.selectedID, evictedTabIDs: evicted, navigatedPath: navigation)
    }

    static func enforceCap(_ state: inout ArtifactsState) -> [String] {
        var removed: [String] = []
        state.tabCap = max(1, state.tabCap)
        while state.tabs.count > state.tabCap {
            let candidate = state.tabs.filter { !$0.pinned && $0.id != state.selectedID }.min(by: oldestFirst)
            guard let candidate else { break }
            removed.append(candidate.id)
            state.tabs.removeAll { $0.id == candidate.id }
        }
        var diffBytes = state.tabs.reduce(UInt64(0)) { total, tab in
            guard case let .change(_, diff, _) = tab.target else { return total }
            let sum = total.addingReportingOverflow(UInt64(diff.utf8.count))
            return sum.overflow ? UInt64.max : sum.partialValue
        }
        guard diffBytes > UInt64(ArtifactsState.maximumRetainedDiffBytes) else { return removed }
        let changes = state.tabs.filter {
            if case .change = $0.target { return !$0.pinned && $0.id != state.selectedID }
            return false
        }.sorted(by: oldestFirst)
        for tab in changes where diffBytes > UInt64(ArtifactsState.maximumRetainedDiffBytes) {
            guard case let .change(_, diff, _) = tab.target else { continue }
            removed.append(tab.id)
            state.tabs.removeAll { $0.id == tab.id }
            diffBytes -= min(diffBytes, UInt64(diff.utf8.count))
        }
        return removed
    }

    /// Whether `.navigate` can retarget this tab. A change snapshot is
    /// immutable, so an address typed there opens as a new tab instead.
    public static func canNavigateInPlace(_ tab: ArtifactTab) -> Bool {
        if case .change = tab.target { return false }
        return true
    }

    /// A file's cached copy is shared by every tab showing it, so a tab that
    /// comes to show a file another tab holds starts from that copy's
    /// metadata. Without it, the tab would show the copy yet ignore the
    /// host's stat observations, which need a baseline.
    static func sharedCache(for target: ArtifactsTarget, hostID: String, in state: ArtifactsState) -> ArtifactsCacheMetadata? {
        guard case .file = target else { return nil }
        return state.tabs.lazy.filter { $0.hostID == hostID && $0.target == target }
            .compactMap(\.cache).max { $0.fetchedAt < $1.fetchedAt }
    }

    /// The tab an automatic open focuses instead of adding one. Several tabs
    /// can share a page's scheme and port: the one at the exact location
    /// wins, then the port's most recently viewed tab, which navigates.
    private static func reusableTab(for target: ArtifactsTarget, hostID: String, in state: ArtifactsState) -> Int? {
        let identity = target.identity
        let matches = state.tabs.indices.filter {
            state.tabs[$0].hostID == hostID && state.tabs[$0].target.identity == identity
        }
        guard case .page = target else { return matches.first }
        return matches.first(where: { state.tabs[$0].target == target })
            ?? matches.max(by: { oldestFirst(state.tabs[$0], state.tabs[$1]) })
    }

    private static func oldestFirst(_ lhs: ArtifactTab, _ rhs: ArtifactTab) -> Bool {
        if lhs.viewedAt != rhs.viewedAt { return lhs.viewedAt < rhs.viewedAt }
        if lhs.openedAt != rhs.openedAt { return lhs.openedAt < rhs.openedAt }
        return lhs.id < rhs.id
    }

    private static func selectFallback(_ state: inout ArtifactsState, hostID: String?, now: Int64) {
        let ordered = state.tabs.sorted(by: ArtifactsOverview.recentFirst)
        let next = ordered.first(where: { $0.hostID == hostID }) ?? ordered.first
        state.selectedID = next?.id
        if let i = state.tabs.firstIndex(where: { $0.id == next?.id }) {
            state.tabs[i].viewedAt = now
            state.tabs[i].unseenChange = false
        }
    }
}
